// Custom AutoCloseable — lock released automatically!
package com.bank.twr.resource;

public class SettlementLock implements AutoCloseable {
    private final String lockId;
    private boolean locked = false;

    public SettlementLock(String lockId) {
        this.lockId = lockId;
        this.locked = true;
        System.out.println(" Lock ACQUIRED: " + lockId);
    }

    public boolean isLocked() { return locked; }
    public String getLockId() { return lockId; }

    @Override
    public void close() {
        locked = false;
        System.out.println(" Lock RELEASED: " + lockId);
        // Called automatically when try block exits!
    }
}
