package com.bank.twr.service;

import com.bank.twr.resource.SettlementLock;

public class TradeImportService {

    // ═══ try-with-resources: lock always released ═══
    public String processWithLock(String batchId, boolean shouldFail) {
        try (SettlementLock lock = new SettlementLock("BATCH-" + batchId)) {
            if (shouldFail) {
                throw new RuntimeException("Settlement failed for batch " + batchId);
            }
            return "Batch " + batchId + " processed successfully";
        }
        // lock.close() called automatically — whether success or exception!
    }

    // ═══ Multiple resources — closed in REVERSE order ═══
    public String multipleResources() {
        try (SettlementLock outer = new SettlementLock("OUTER");
             SettlementLock inner = new SettlementLock("INNER")) {
            return "Both locked. Inner: " + inner.getLockId() + ", Outer: " + outer.getLockId();
        }
        // Close order: INNER first, then OUTER (reverse declaration order!)
    }
}
