// ─── File: src/test/java/com/bank/twr/TryWithResourcesTest.java ───
package com.bank.twr;

import com.bank.twr.resource.SettlementLock;
import com.bank.twr.service.TradeImportService;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class TryWithResourcesTest {

    TradeImportService service = new TradeImportService();

    @Test
    void autoCloseOnSuccess() {
        SettlementLock lock;
        try (SettlementLock l = new SettlementLock("TEST")) {
            lock = l;
            assertThat(lock.isLocked()).isTrue();  // locked inside try
        }
        assertThat(lock.isLocked()).isFalse();  // auto-closed after try!
    }

    @Test
    void autoCloseOnException() {
        SettlementLock[] lockRef = new SettlementLock[1];
        assertThatThrownBy(() -> {
            try (SettlementLock lock = new SettlementLock("FAIL")) {
                lockRef[0] = lock;
                throw new RuntimeException("boom");
            }
        }).isInstanceOf(RuntimeException.class);
        assertThat(lockRef[0].isLocked()).isFalse();  // STILL auto-closed despite exception!
    }

    @Test
    void serviceWithLock_successReleasesLock() {
        String result = service.processWithLock("001", false);
        assertThat(result).contains("successfully");
        // Lock released automatically after success
    }

    @Test
    void serviceWithLock_failureStillReleasesLock() {
        assertThatThrownBy(() -> service.processWithLock("002", true))
            .isInstanceOf(RuntimeException.class);
        // Lock released automatically EVEN on failure!
    }

    @Test
    void suppressedException_bothVisible() {
        try {
            try (AutoCloseable res = () -> { throw new Exception("CLOSE_ERR"); }) {
                throw new RuntimeException("MAIN_ERR");
            }
        } catch (Exception e) {
            assertThat(e.getMessage()).isEqualTo("MAIN_ERR");           // primary
            assertThat(e.getSuppressed()).hasSize(1);
            assertThat(e.getSuppressed()[0].getMessage()).isEqualTo("CLOSE_ERR"); // suppressed
            // BOTH visible! Nothing lost!
        }
    }

    @Test
    void multipleResources_closedInReverseOrder() {
        String result = service.multipleResources();
        assertThat(result).contains("INNER").contains("OUTER");
        // Console output: OUTER acquired → INNER acquired → INNER released → OUTER released
        // Reverse order ensures inner resources closed before outer!
    }
}
